#include <bits/stdc++.h>using namespace std; #define fastio() ios::sync_with_stdio(false); cin.tie(NULL); cout.tie(NULL) typedef long long ll; void solve(){    int n;    cin>>n;    vector<int>ans(3*n);    int a=1;    for(int i=0; i<3*n; i+=3){        ans[i]=a;        a++;    }    int i=1;    while(i<3*n){        ans[i]=a;        if(i%3==2) i+=2;        else i++;        a++;    }    for(auto &x: ans) cout<<x<<" ";    cout<<endl;}int main() {    fastio();     int t = 1;    cin >> t;    while (t--) {        solve();    }     return 0;}